<?php
require_once __DIR__.'/../includes/helpers.php';require_role(['ADMINISTRADOR']);header('Content-Type: application/json; charset=utf-8');
try {csrf_check();$pdo=db();$a=$_POST['accion']??'';
 if ($a==='crear') {$nombre=trim($_POST['nombre']??'');$loc=(int)($_POST['localidad_id']??0);if ($nombre===''||!$loc)throw new Exception('Nombre y localidad son obligatorios.');$check=$pdo->prepare('SELECT id FROM estaciones WHERE nombre=? AND localidad_id=? LIMIT 1');$check->execute([$nombre,$loc]);if ($check->fetch())throw new Exception('Ya existe una estación con ese nombre en esa localidad. Puedes usar el mismo nombre en otra localidad.');$st=$pdo->prepare('INSERT INTO estaciones(nombre,localidad_id,activo) VALUES(?,?,1)');try {$st->execute([$nombre,$loc]);}catch (PDOException $e) {if ($e->getCode()==='23000')throw new Exception('Ya existe una estación con ese nombre en esa localidad. Puedes usar el mismo nombre en otra localidad.');throw $e;}$pdo->prepare('UPDATE localidades SET cantidad_estaciones=(SELECT COUNT(*) FROM estaciones WHERE localidad_id=? AND activo=1) WHERE id=?')->execute([$loc,$loc]);echo json_encode(['ok'=>true]);exit;}
 if ($a==='toggle') {$id=(int)($_POST['id']??0);$q=$pdo->prepare('SELECT localidad_id FROM estaciones WHERE id=? LIMIT 1');$q->execute([$id]);$loc=(int)$q->fetchColumn();$st=$pdo->prepare('UPDATE estaciones SET activo=1-activo WHERE id=?');$st->execute([$id]);if ($loc)$pdo->prepare('UPDATE localidades SET cantidad_estaciones=(SELECT COUNT(*) FROM estaciones WHERE localidad_id=? AND activo=1) WHERE id=?')->execute([$loc,$loc]);echo json_encode(['ok'=>true]);exit;}
 if ($a==='eliminar') {$id=(int)($_POST['id']??0);if (!$id)throw new Exception('Estación inválida.');$q=$pdo->prepare('SELECT id,nombre,localidad_id FROM estaciones WHERE id=? LIMIT 1');$q->execute([$id]);$station=$q->fetch();if (!$station)throw new Exception('La estación no existe.');$q=$pdo->prepare('SELECT COUNT(*) FROM usuarios WHERE estacion_id=?');$q->execute([$id]);$users=(int)$q->fetchColumn();if ($users>0)throw new Exception('No puedes eliminar esta estación porque tiene '.$users.' usuario(s) asignado(s). Reasígnalos primero.');$q=$pdo->prepare("SELECT COUNT(*) FROM turnos WHERE estacion_id=? AND estado IN ('LLAMADO','ATENDIENDO')");$q->execute([$id]);$active=(int)$q->fetchColumn();if ($active>0)throw new Exception('No puedes eliminar esta estación mientras tenga turnos llamados o en atención. Finaliza o reasigna esos turnos primero.');$pdo->beginTransaction();try {$pdo->prepare('INSERT INTO auditoria(usuario_id,accion,detalle) VALUES(?,?,?)')->execute([(int)user()['id'],'ELIMINAR_ESTACION','Estación eliminada: '.$station['nombre']]);$del=$pdo->prepare('DELETE FROM estaciones WHERE id=? LIMIT 1');$del->execute([$id]);if ($del->rowCount()!==1)throw new Exception('No fue posible eliminar la estación.');$pdo->prepare('UPDATE localidades SET cantidad_estaciones=(SELECT COUNT(*) FROM estaciones WHERE localidad_id=? AND activo=1) WHERE id=?')->execute([(int)$station['localidad_id'],(int)$station['localidad_id']]);$pdo->commit();}catch (Throwable $e) {if ($pdo->inTransaction())$pdo->rollBack();throw $e;}echo json_encode(['ok'=>true,'mensaje'=>'Estación eliminada correctamente.']);exit;}
 throw new Exception('Acción no válida.');
}catch (Throwable $e) {http_response_code(400);echo json_encode(['ok'=>false,'error'=>$e->getMessage()]);}
